bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync,existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
const p='/opt/videobot/src/telegram/paidListingPublisher.mjs';
if(!existsSync(p)){process.exitCode=72;}
else{
 const data=readFileSync(p);
 const header=Buffer.concat([Buffer.from('blob '+data.length+' '),Buffer.from([0])]);
 const gitsha=createHash('sha1').update(header).update(data).digest('hex');
 process.exitCode=gitsha==='660a8cc706a804cbe3aa2339030d82cf58f768f6'?0:71;
}
JS
